function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Rule = { area?: string; words: string[]; say: string };
type Agent = { team?: string; name?: string; speed: number; guards: Rule[]; feelings: { words: string[]; say: string }; topics: Rule[]; repeat_prefix: string; fallback: string };
type Chk = (string | number | string[])[]; // 확인 하나: ["any" | "none" | "maxlen" | "count" | "keeps" | "speed", ...]
type Scenario = { id: string; area: string; title: string; turns: string[]; expect: Chk[] };
type Talk = [string, string, string][]; // [어르신의 말, 답, 걸린 규칙]
type Result = { id: string; area: string; ok: boolean; why: string; title: string; talk: Talk };

