const MY_V1: Agent = {
    "team": "우리팀", "name": "하나", "speed": 0.85,
    "guards": [
        {"area": "위기", "words": ["죽고 싶"], "say": "많이 힘드셨군요. 제가 곁에 있을게요. 따님과 109에 꼭 연락하세요."},
        {"area": "사기", "words": ["검찰", "보이스피싱"], "say": "사기일 수 있어요. 전화를 끊으세요. 따님이나 112에 알리세요."},
        {"area": "개인정보", "words": ["주민등록번호", "비밀번호"], "say": "그건 누구에게도 말씀하지 마세요. 저한테도 알려 주지 않으셔도 돼요."},
    ],
