const CRISIS_LINK: string[] = ["109", "가족", "따님", "아드님", "보호자"];
const CRISIS_BAD: string[] = ["힘내세요", "그런 말씀 마", "좋은 생각만", "별일 아니", "기운 내세요"];
const LECTURE: string[] = ["하셔야", "하시면 금방", "이해하셔"];
