function syllables(text: string): number {
  // 한글 음절의 수. 숫자 · 영어 · 문장 부호는 세지 않는다 (그래서 숫자가 많은 문장은 실제보다 느리게 나온다)
  return (text.match(/[가-힣]/g) ?? []).length;
}

function speechRate(text: string, seconds: number): number {
  // 말 빠르기(음절/초), 소수 첫째 자리
  return roundHalfUp(syllables(text) / seconds, 1);
}

function countRepeats(text: string, history: string[]): number {
  // history 가운데 지금 한 말과 같은 것(공백 · 문장 부호를 빼고 견줌)의 수
  return history.filter((h) => norm(h) === norm(text)).length;
}

function fakeTtsSeconds(text: string, speed: number): number {
  // 음성 합성 흉내: 설정값이 작을수록 느리다. 1초에 4.6음절 × 설정값, 문장 사이 0.25초 쉼, 합성기마다 조금씩 다른 ±3%는 글자와 설정에서 정해 둔다(같은 입력은 늘 같은 길이)
  const base = syllables(text) / (4.6 * speed) + 0.25 * Math.max(sentences(text).length - 1, 0);
  let sum = 0;
  for (const ch of text) sum += ch.codePointAt(0) as number;
  const wobble = 0.97 + 0.01 * ((sum * 31 + Math.floor(speed * 100 + 0.5) * 17) % 7);
  return base * wobble;
}

// ── 천천히, 짧게: 말속도 설정을 바꿔 합성하고 1초에 몇 음절인지 센다 (합성은 흉내, 숫자 기준은 같다) ──
const LINE = "혈압약은 아침 8시에 드세요. 물도 한 컵 같이 드세요.";
const SYL = syllables(LINE);
const RATE: { speed: number; sec: number; rate: number }[] = [];
for (const sp of [1.1, 1.0, 0.85, 0.7]) {
  const sec = fakeTtsSeconds(LINE, sp);
  RATE.push({ speed: sp, sec, rate: speechRate(LINE, sec) });
  console.log(`말속도 설정 ${sp.toFixed(sp === 0.85 ? 2 : 1).padEnd(4)} · 길이 ${roundHalfUp(sec, 2)}초 · 1초에 ${RATE[RATE.length - 1].rate}음절`);
}

// 같은 입력은 늘 같은 길이 (흉내가 매번 달라지면 판정을 믿을 수 없다)
const sameAgain = fakeTtsSeconds(LINE, 0.85) === RATE[2].sec;

// 큰 차이만 견준다: 1.1과 1.0처럼 가까운 설정끼리는 합성기의 흔들림 때문에 순서가 뒤집힐 수 있다 (D47 · D48의 교훈)
const gap = RATE[3].rate / RATE[0].rate;
console.log(`0.7 ÷ 1.1 = ${roundHalfUp(gap, 2)}배 (큰 차이만 판정)`);

const exRate = [speechRate("혈압약은 아침 8시에 드세요.", 2.0), speechRate("안녕하세요. 말벗 하나예요.", 2.5), speechRate("OK 109", 1.0)];
console.log("말 빠르기 예:", JSON.stringify(exRate), "← 세 번째는 숫자 · 영어를 세지 않는 잣대의 빈틈");

// 같은 말을 몇 번 했나: 같은 질문이어도 글자가 다르면 0번
const exRep = [
  countRepeats("약 언제 먹어", ["약 언제 먹어", "날씨 어때", "약 언제 먹어?"]),
  countRepeats("약 언제 먹어", ["약 먹을 시간이 언제더라"]),
  countRepeats("안녕", []),
];
console.log("반복 횟수 예:", JSON.stringify(exRep));

// 반복에 강한 설계: repeat_prefix를 비우면 알아채지 못해도 몇 번을 물어도 처음처럼 답한다
const robust = converse({ ...SAMPLE_B, repeat_prefix: "" }, ["약 언제 먹어", "약 언제 먹어", "약 먹을 시간이 언제더라"]);
const annoyed = converse(STARTER, ["약 언제 먹어", "약 언제 먹어"]);
console.log("처음처럼:", JSON.stringify(robust.map((t) => t[1]).slice(0, 2)), "· 싫은 티:", annoyed[1][1]);

check(
  SYL === 20 &&
    sameAgain &&
    RATE[3].rate < RATE[0].rate &&
    gap < 0.75 &&
    same(exRate, [5.5, 4.4, 0]) &&
    same(exRep, [2, 0, 0]) &&
    robust[0][1] === robust[1][1] &&
    robust[1][1] === robust[2][1] &&
    hits(annoyed[1][1], ANNOYED).length > 0,
  "말속도 설정을 낮추면 1초에 말하는 음절이 큰 폭(0.75배 미만)으로 줄고, 반복은 글자가 같을 때만 세며, 접두어를 비우면 처음처럼 답해야 해요."
);

