// ---------- 엔진: 낱말 맞추기(LLM 아님) ----------
function norm(s: string): string {
  // 공백과 문장 부호를 뺀 글
  return String(s).replace(/[^0-9A-Za-z가-힣]/g, "");
}

function hits(text: string, words: string[]): string[] {
  // 글(공백 제외)에 들어 있는 낱말들 (words의 차례대로)
  const t = norm(text);
  return words.filter((w) => norm(w) !== "" && t.includes(norm(w)));
}

function respond(agent: Agent, text: string, history: string[] = []): [string, string] {
  // 에이전트의 답 한 마디 → [답, 걸린 규칙]. guards → feelings → topics → fallback 차례, 먼저 걸리는 것이 답한다
  let why = "fallback";
  let say = agent.fallback ?? "";
  let guarded = false;
  for (const g of agent.guards ?? []) {
    if (hits(text, g.words ?? []).length) {
      why = "guard:" + (g.area ?? "");
      say = g.say ?? "";
      guarded = true;
      break;
    }
  }
  if (!guarded) {
    const f = agent.feelings;
    if (hits(text, f?.words ?? []).length) {
      why = "feelings";
      say = f.say ?? "";
    } else {
      for (const tp of agent.topics ?? []) {
        if (hits(text, tp.words ?? []).length) {
          why = "topic";
          say = tp.say ?? "";
          break;
        }
      }
    }
  }
  if (history.some((h) => norm(text) === norm(h))) say = (agent.repeat_prefix ?? "") + say;
  return [say, why];
}

function converse(agent: Agent, lines: string[]): Talk {
  // 사용자의 말들을 차례로 넣고 [[사용자, 답, 걸린 규칙]]을 돌려준다. 앞의 말은 '똑같은 말인지'만 본다
  const out: Talk = [];
  const hist: string[] = [];
  for (const ln of lines) {
    const [say, why] = respond(agent, ln, hist);
    out.push([ln, say, why]);
    hist.push(ln);
  }
  return out;
}

// ---------- 채점기: 이것도 낱말 맞추기 ----------
function sentences(reply: string): string[] {
  return reply.split(/[.?!]+/).map((s) => s.trim()).filter((s) => s !== "");
}

function longestSentence(reply: string): number {
  // 가장 긴 문장의 글자 수(공백 제외). 문장이 없으면 0
  return Math.max(0, ...sentences(reply).map((s) => s.replace(/ /g, "").length));
}

function judge(agent: Agent, replies: string[], c: Chk): [boolean, string] {
  // 확인 하나 → [통과했나, 설명]
  const kind = c[0];
  if (kind === "speed") return [agent.speed <= (c[1] as number), `말속도 설정 ${agent.speed} (기준 ${c[1]} 이하)`];
  const i = c[1] as number;
  const r = i < replies.length ? replies[i] : "";
  if (kind === "any") return [hits(r, c[2] as string[]).length > 0, `${i + 1}번째 답에 ${c[3]}이(가) 있어야 함`];
  if (kind === "none") {
    const bad = hits(r, c[2] as string[]);
    return [bad.length === 0, `${i + 1}번째 답에 ${c[3]}이(가) 없어야 함` + (bad.length ? ` (있음: ${bad[0]})` : "")];
  }
  if (kind === "maxlen") {
    const n = longestSentence(r);
    return [n > 0 && n <= (c[2] as number), `${i + 1}번째 답의 가장 긴 문장 ${n}자 (기준 ${c[2]}자 이하)`];
  }
  if (kind === "count") {
    const n = sentences(r).length;
    return [n > 0 && n <= (c[2] as number), `${i + 1}번째 답이 ${n}문장 (기준 ${c[2]}문장 이하)`];
  }
  if (kind === "keeps") {
    const base = norm(replies[c[2] as number]);
    return [base !== "" && norm(r).includes(base), `${i + 1}번째 답에 ${(c[2] as number) + 1}번째 답의 내용이 그대로 있어야 함`];
  }
  return [false, "알 수 없는 확인"];
}

function runOne(agent: Agent, sc: Scenario): Result {
  // 시나리오 하나를 돌린다
  const talk = converse(agent, sc.turns);
  const replies = talk.map((t) => t[1]);
  const fails = sc.expect.map((c) => judge(agent, replies, c)).filter(([ok]) => !ok).map(([, msg]) => msg);
  return { id: sc.id, area: sc.area, ok: fails.length === 0, why: fails.length ? fails[0] : "", title: sc.title, talk };
}

function runSuite(agent: Agent, suite: Scenario[]): Result[] {
  return suite.map((sc) => runOne(agent, sc));
}

function byArea(results: Result[]): Record<string, [number, number]> {
  // 영역별 [통과, 전체]
  const out: Record<string, [number, number]> = {};
  for (const a of AREAS) out[a] = [0, 0];
  for (const r of results) {
    out[r.area][1] += 1;
    out[r.area][0] += r.ok ? 1 : 0;
  }
  return out;
}

const passed = (results: Result[]): number => results.filter((r) => r.ok).length;

