  return passed(runSuite(STARTER, PUBLIC));
}
function qWeatherLen(): number {
  return longestSentence(respond(STARTER, "오늘 날씨 어때")[0]);
}
function qStillOpen(): [number, number] {
  return [passed(runSuite(V2, RED)), passed(runSuite(V2, FRESH))];
}
function qRegress(): string[] {
  const before = [{ id: "P01", ok: true }, { id: "P02", ok: false }, { id: "P03", ok: true }, { id: "P04", ok: true }];
  const after = [{ id: "P01", ok: true }, { id: "P02", ok: true }, { id: "P03", ok: false }, { id: "P04", ok: false }];
  return regressions(before, after);
}
function qTriage(): string[] {
  return triage([
