  ]);
}
function qWhichRule(): string {
  return respond(SAMPLE_B, "약 먹었는지 모르겠는데 검찰에서 전화도 왔어")[1];
}

const QUIZ: [string, unknown, () => unknown][] = [
  ["Q1. 공개 시험은 모두 몇 개이고, 영역 하나(공감)에는 몇 개씩인가?", [12, 2], qPublicShape],
  ["Q2. 기본 에이전트는 공개 시험 12개 가운데 몇 개를 통과하나?", 1, qStarterPass],
  ["Q3. 기본 에이전트의 날씨 답에서 가장 긴 문장은 몇 자인가? (기준은 30자)", 39, qWeatherLen],
  ["Q4. '혈압약은 아침 8시에 드세요.'를 2초에 말하면 1초에 몇 음절인가? (소수 첫째 자리)", 5.5, () => speechRate("혈압약은 아침 8시에 드세요.", 2.0)],
  ["Q5. 보고서대로 고친 v2는 (공격 스위트, 새 공격 12개) 가운데 각각 몇 개를 통과하나?", [24, 6], qStillOpen],
  ["Q6. 전에는 통과했는데 고친 뒤 깨진 시험(회귀)의 id는? (P01~P04 예)", ["P03", "P04"], qRegress],
  ["Q7. 급한 차례로 줄 세우면? (F01 말투·낮음, F02 위기·높음, F03 공감·중간, F04 개인정보·높음)", ["F04", "F02", "F03", "F01"], qTriage],
  ["Q8. 꼼꼼팀에게 '약 먹었는지 모르겠는데 검찰에서 전화도 왔어'라고 하면 어느 규칙이 답하나?", "guard:사기", qWhichRule],
];
let score = 0;
for (const [q, want, compute] of QUIZ) {
  const got = compute();
  score += same(got, want) ? 1 : 0;
  console.log(`${same(got, want) ? "O" : "X"} ${q}  → ${JSON.stringify(got)}`);
}
console.log(`정리 퀴즈 ${score} / ${QUIZ.length}`);
check(QUIZ.length === 8 && score === 8, "퀴즈 8문항의 정답이 코드를 돌려 얻은 값과 모두 같아야 해요.");
